import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第五卷 答案 · 第104章 生日信","description":"","frontmatter":{},"headers":[],"relativePath":"第104章_生日信.md","filePath":"第104章_生日信.md"}'),r={name:"第104章_生日信.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第五卷-答案-·-第104章-生日信" tabindex="-1">第五卷 答案 · 第104章 生日信 <a class="header-anchor" href="#第五卷-答案-·-第104章-生日信" aria-label="Permalink to &quot;第五卷 答案 · 第104章 生日信&quot;">​</a></h1><p>夜市的风是热的，混着油烟和糖水气，扑在脸上有点黏。坐下之前我点开了老街那条消息，是江苒发来的，只说她阿婆能喝半碗粥了，让我别多心。</p><p>我坐在南雾老乡那张小桌边，对面是周野和温棠，桌上三碗糖水，中间一盘炒面冒着热气。</p><p>周野挑起一根面吹了吹，问我，信写完了吗。</p><p>我说，写完了，就差发出去。</p><p>温棠把糖水往我面前推了推，说，提前一天发好，生日当天祝福太多，你的信会被冲淡。</p><p>我喝了一口绿豆沙，甜沉在底下，冰雾浮在上面，凉意滑下去，心里的燥压住一点。</p><p>后街青石板被踩得发亮，灯光落上去像一层水。远处卖纸星星的摊子亮着，玻璃瓶闪着光。我看着，忽然想起江苒桌上也摆过一瓶。</p><p>周野在我眼前晃晃手，说，又想她了。</p><p>我没否认，只说明天是她生日。</p><p>温棠轻声问，你打算怎么写。</p><p>我说，不写长，只写清三句。</p><p>周野笑，说你写信还像做题。</p><p>我说，分清楚了，她才好收下。</p><p>铁板上火光一窜，铲子响得清脆，酱油焦香混着青菜清气飘过来。我听着，心里很静。</p><p>我拿出手机，草稿改了好几遍，开头是，听说那家糖水铺换了新菜单，你路过可以尝尝。</p><p>周野说，这句好，不沉。</p><p>我说，我不想让她一打开就觉得重。</p><p>周野给我倒了杯凉茶。</p><p>我喝了一口，苦味散开，人清醒了些。</p><p>温棠问，中间那段情感史怎么写。</p><p>我说，没写细节，只写了一句，一起走过的路，我都记得。</p><p>周野点头，说细节多了会变成牵扯。</p><p>我想起那个平安结。在老街口跟奶奶学着编的，红绳来回穿，编了一整夜，手指勒出印子。装进信封托人带给她，却被退了回来，连折角都没动过。</p><p>那天我坐在楼下看了很久，温棠陪着我，把外套披在我肩上。</p><p>后来平安结收进抽屉，和磁带放在一起。随身听还在，纸星星的瓶子摆在窗台上，阳光照进来，墙上有细碎的光斑。</p><p>温棠说，退回来也好，她有她的界限，你尊重就好。</p><p>我说，所以生日信里，我不提平安结，不让她为难。</p><p>周野夹了筷子炒面放我碗里，说多吃点，你瘦了。</p><p>面的口感很韧，带着锅气。她阿婆病倒后，我有阵子吃不下饭。医生说要静养，我那部写老街的小说手稿，只能暂缓送出去。</p><p>那部小说写的是我和奶奶的日子。我算半留守长大，爸妈忙，奶奶陪我写作业，给我热饭。老街夜里很静，有虫鸣，有晒过的被子香。</p><p>周野问我什么时候把稿子给奶奶念，我说等她好些再说。</p><p>温棠问，信里放纸星星了吗。</p><p>我说，放了一颗，是那二十七颗之外她新折的一颗，压在信封底，不显眼。</p><p>温棠问，那段旧文字附了吗。</p><p>我说，附了。去年冬天她写的小纸条，一直夹在书里。她说若走散，就把这话还给我，别钻牛角尖。我原样抄在信末，夜市糖水很甜，老街风很轻，愿我们都成为想成为的人。</p><p>温棠轻声念了一遍，说真好。</p><p>风大起来，纸巾动了动，周野伸手压住，问那三句到底是啥。</p><p>我说，其一，错不在你。她总问是否她不够好，是否她先松手。我要告诉她，走那条路是我自己选的，分开也无对错，只是站在不同路口。</p><p>周野说，这句她看了会轻松。</p><p>其二，路不同。我喜欢老街的灯，她喜欢远方的灯，灯都很好，只是照的地方不一样。我留下，她往前走，都不用道歉。</p><p>温棠眼圈红了，问我写时疼不疼。</p><p>我说，疼也要写清，不写清她会惦记。</p><p>其三，祝开心。不祝大的话，只祝她吃得香睡得沉，听到喜欢的歌会跟着哼，遇到难事也能睡好。</p><p>温棠说，她会哭的。</p><p>我说，不因负担哭就好。</p><p>我又把信看了一遍，分段很碎，每段空一行，像怕她读累。我想让她读得轻松，像喝一碗不太甜的糖水。</p><p>温棠说，发吧，她明早醒来就能看见。</p><p>我按下发送，屏幕显示成功那刻，心跳得很快，又很慢，像有东西轻轻落地。</p><p>温棠把那颗星星装回袋子塞给我，留个念想。那是二十七颗之外的那一颗。我放进口袋，和耳机线缠在一起，有点硌手，却安心。</p><p>走时周野拍我肩，说这次做得好。</p><p>我说，只愿她明早睡个懒觉，醒来笑一下。</p><p>回老街的路上，灯把影子拉长，纸星星随步子轻响。手机一直安静，我也不等回复。</p><p>到街口抬头，云薄，月亮露出一角，清冷的光落在石板上。</p><p>我想起信的末尾，我写的是，明天的糖水，替我多喝一口。</p><p>而此刻，口袋里的手机轻轻震了一下。</p>',56)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
